style.css:
@-moz-document domain("youtube.com") {
/* === ОБЩИЙ СТИЛЬ === */
  * {
    font-family: 'Times New Roman', Times, serif !important;
  }

  body {
    background-color: #c0c0c0 !important;
    background-image: none !important;
    color: #000 !important;
  }

  /* === ШАПКА === */
  #header, ytd-app #header {
    background: linear-gradient(to bottom, #000080, #1010a0) !important;
    border-bottom: 3px outset #fff !important;
    padding: 10px !important;
  }

  #logo-icon, ytd-app #logo-icon {
    display: none !important;
  }

  #logo-text, ytd-app #logo-text {
    font-family: 'Comic Sans MS', cursive !important;
    font-size: 32px !important;
    color: #ff0000 !important;
    text-shadow: 2px 2px 0 #fff !important;
    font-weight: bold !important;
  }

  /* === ПОИСК === */
  #search, ytd-app #search {
    background: #fff !important;
    border: 2px inset #808080 !important;
    padding: 5px !important;
  }

  #search-input, ytd-app #search-input {
    background: #fff !important;
    border: 2px inset #c0c0c0 !important;
    font-family: 'Courier New', monospace !important;
    font-size: 14px !important;
    color: #000 !important;
  }

  #search-icon-legacy, ytd-app #search-icon-legacy {
    background: #c0c0c0 !important;
    border: 2px outset #fff !important;
    color: #000 !important;
    font-weight: bold !important;
  }

  /* === КНОПКИ === */
  button, ytd-button-renderer {
    background: #c0c0c0 !important;
    border: 2px outset #fff !important;
    color: #000 !important;
    font-family: 'MS Sans Serif', sans-serif !important;
    font-size: 12px !important;
    padding: 4px 12px !important;
    cursor: pointer !important;
  }

  button:active, ytd-button-renderer:active {
    border: 2px inset #fff !important;
  }

  /* === ВИДЕО КАРТОЧКИ === */
  ytd-video-renderer, ytd-compact-video-renderer {
    background: #fff !important;
    border: 2px ridge #808080 !important;
    padding: 10px !important;
    margin: 5px !important;
  }

  ytd-video-renderer:hover, ytd-compact-video-renderer:hover {
    background: #ffffcc !important;
  }

  /* === ЗАГОЛОВКИ ВИДЕО === */
  #video-title, ytd-video-renderer #video-title {
    color: #0000ff !important;
    font-size: 16px !important;
    text-decoration: underline !important;
    font-weight: bold !important;
  }

  #video-title:visited, ytd-video-renderer #video-title:visited {
    color: #800080 !important;
  }

  /* === ОПИСАНИЕ КАНАЛА === */
  #channel-name, ytd-video-renderer #channel-name {
    color: #008000 !important;
    font-size: 12px !important;
  }

  #metadata-line, ytd-video-renderer #metadata-line {
    color: #808080 !important;
    font-size: 11px !important;
  }

  /* === ПЛЕЕР === */
  #movie_player, ytd-player #movie_player {
    background: #000 !important;
    border: 3px inset #808080 !important;
  }

  /* === КОММЕНТАРИИ === */
  ytd-comment-thread-renderer {
    background: #fff !important;
    border: 2px groove #808080 !important;
    padding: 10px !important;
    margin: 10px 0 !important;
  }

  #author-text, ytd-comment-renderer #author-text {
    color: #0000ff !important;
    font-weight: bold !important;
    text-decoration: underline !important;
  }

  #content-text, ytd-comment-renderer #content-text {
    color: #000 !important;
    font-size: 14px !important;
  }

  /* === БОКОВАЯ ПАНЕЛЬ === */
  #secondary, ytd-watch-flexy #secondary {
    background: #c0c0c0 !important;
    border: 2px outset #fff !important;
    padding: 10px !important;
  }

  /* === ПОДПИСКИ === */
  ytd-subscribe-button-renderer {
    background: #ff0000 !important;
    border: 2px outset #fff !important;
    color: #fff !important;
    font-weight: bold !important;
  }

  /* === ЛАЙКИ/ДИЗЛАЙКИ === */
  #like-button, ytd-menu-renderer #like-button {
    background: #00ff00 !important;
    border: 2px outset #fff !important;
    color: #000 !important;
  }

  #dislike-button, ytd-menu-renderer #dislike-button {
    background: #ff0000 !important;
    border: 2px outset #fff !important;
    color: #fff !important;
  }

  /* === СКРОЛЛБАР === */
  ::-webkit-scrollbar {
    width: 16px !important;
    height: 16px !important;
  }

  ::-webkit-scrollbar-track {
    background: #c0c0c0 !important;
    border: 1px inset #808080 !important;
  }

  ::-webkit-scrollbar-thumb {
    background: #c0c0c0 !important;
    border: 2px outset #fff !important;
  }

  ::-webkit-scrollbar-button {
    background: #c0c0c0 !important;
    border: 2px outset #fff !important;
    width: 16px !important;
    height: 16px !important;
  }

  /* === ФУТЕР === */
  #footer, ytd-app #footer {
    background: #c0c0c0 !important;
    border-top: 3px outset #fff !important;
    padding: 20px !important;
    text-align: center !important;
    font-size: 12px !important;
  }

  /* === ДОБАВЛЕНИЕ РЕТРО ЭЛЕМЕНТОВ === */
  body::before {
    content: "? This page is under construction " !important;
    display: block !important;
    text-align: center !important;
    background: #ffff00 !important;
    color: #ff0000 !important;
    padding: 10px !important;
    font-weight: bold !important;
    font-size: 18px !important;
    border: 3px ridge #ff0000 !important;
    margin: 10px !important;
    animation: blink 1s infinite !important;
  }

  @keyframes blink {
    0%, 50% { opacity: 1; }
    51%, 100% { opacity: 0; }
  }

  body::after {
    content: "Best viewed in Netscape Navigator 4.0 | Resolution: 800x600 | © 1998 YouTube Inc." !important;
    display: block !important;
    text-align: center !important;
    background: #000080 !important;
    color: #fff !important;
    padding: 10px !important;
    font-size: 11px !important;
    margin-top: 20px !important;
  }

  /* === ССЫЛКИ === */
  a {
    color: #0000ff !important;
    text-decoration: underline !important;
  }

  a:visited {
    color: #800080 !important;
  }

  a:hover {
    color: #ff0000 !important;
    background: #ffff00 !important;
  }

  /* === ТАБЛИЦЫ (если есть) === */
  table {
    border: 2px ridge #808080 !important;
    background: #fff !important;
  }

  td, th {
    border: 1px solid #808080 !important;
    padding: 5px !important;
  }

  /* === ИЗОБРАЖЕНИЯ === */
  img {
    border: 2px outset #fff !important;
  }

  /* === ВЫДЕЛЕНИЕ ТЕКСТА === */
  ::selection {
    background: #000080 !important;
    color: #fff !important;
  }

  /* === МЕНЮ === */
  ytd-section-list-renderer {
    background: #c0c0c0 !important;
    border: 2px outset #fff !important;
    padding: 10px !important;
  }

  /* === ЗАГОЛОВКИ СЕКЦИЙ === */
  h1, h2, h3, h4 {
    color: #000080 !important;
    border-bottom: 2px solid #000080 !important;
    padding-bottom: 5px !important;
  }

  /* === ТЕКСТОВЫЕ ПОЛЯ === */
  input, textarea {
    background: #fff !important;
    border: 2px inset #808080 !important;
    font-family: 'Courier New', monospace !important;
    padding: 5px !important;
  }

  /* === ЧЕКБОКСЫ И РАДИО === */
  input[type="checkbox"], input[type="radio"] {
    border: 2px inset #808080 !important;
  }

  /* === ВЫПАДАЮЩИЕ СПИСКИ === */
  select {
    background: #fff !important;
    border: 2px inset #808080 !important;
    font-family: 'MS Sans Serif', sans-serif !important;
  }

  /* === РАЗДЕЛИТЕЛИ === */
  hr {
    border: none !important;
    border-top: 2px groove #808080 !important;
    margin: 20px 0 !important;
  }

  /* === ЦИТАТЫ === */
  blockquote {
    background: #ffffcc !important;
    border-left: 5px solid #000080 !important;
    padding: 10px !important;
    margin: 10px 0 !important;
    font-style: italic !important;
  }

  /* === КОД === */
  code, pre {
    background: #000 !important;
    color: #0f0 !important;
    font-family: 'Courier New', monospace !important;
    padding: 10px !important;
    border: 2px inset #808080 !important;
  }
}
